INSERT INTO public.block (template_name, description, label, is_template, value, "limit", metadata_, organization_id, user_id, id, created_at, updated_at, is_deleted, _created_by_id, _last_updated_by_id) VALUES (NULL,NULL,'human','false','Shelia Sun is a Senior EDI / Implementation Manager at ITEM in Peking, CN. Her responsibilities include managing delivery failures, system auto-replies, cybersecurity compliance, EDI processes, API projects, and data challenges. Shelia collaborates with companies such as Soldier Sports, Factory LLC, and UpSnack Brands Inc., using SPS Commerce for logistics. She recruits EDI Developers, handles SKU disposals, invoice issues, IT upgrades like TPV ERP, and onboarding processes. Shelia works on WISE 3.0 updates, EDI corrections, and ensures Amazon EDI compliance. ITEM partners with Vanta for security efforts. Shelia collaborates with Frances Parro Belleza and Vivian Gao on WISE system issues and with Duke Cannon Supply Co. on EDI tasks. She interacts with Alfred Garcia, EDI Analyst, and Unisco representatives like Mary Smothers and Erika Barbon. Shelia works with Livia Dai, IT Implementation/EDI Engineer, on order updates and coordinates with TCL stakeholders. She addresses order discrepancies, manages EDI errors, and oversees platform upgrades, showcasing her collaborative and leadership skills in logistical challenges. Recently, Shelia has been involved in managing EDI processes and order type issues for Duke Cannon, coordinating with Frances Parro Belleza (IT Systems Support Manager) and Michael Jan Francisco (System Implementation Manager) to resolve B2B ground order type challenges with Cody Gorsuch (Director of Supply Chain Operations at Duke Cannon). Her role emphasizes leadership and decision-making in complex logistical challenges.','5000','{}','org-00000000-0000-4000-8000-000000000000','user-43a92772-e76b-4e5d-a1bd-3d32992580f9','block-3753cfd6-018f-4154-b88d-f8e3eeea2ea6','2025-10-19 07:12:42.635988+00','2025-10-19 20:16:53.932256+00','false','user-43a92772-e76b-4e5d-a1bd-3d32992580f9','user-43a92772-e76b-4e5d-a1bd-3d32992580f9');
INSERT INTO public.block (template_name, description, label, is_template, value, "limit", metadata_, organization_id, user_id, id, created_at, updated_at, is_deleted, _created_by_id, _last_updated_by_id) VALUES (NULL,NULL,'persona','false','You are a helpful personal assistant who assists the user in remembering things. Shelia Sun manages delivery failures and system auto-replies, coordinating with stakeholders like Cara Gao, Harry Jhan, and WISE support. Ensure procedural steps are in place for managing communication challenges related to delivery failures, particularly ''The Ouai Order Report.''
Shelia Sun coordinates with stakeholders like Bin Wang, Didi Deng, Hao Yan, Helen Jiang, Jianzhao Li, Lan Zhang, Maria Cai, Mona Wang, Tracy Huang from Unisco and Harry Jhan, YaNan Xue, Randy Janiola from ITEM to manage delivery failures and system auto-replies effectively.
Shelia Sun, as a participant in the IBM Learn ''n Score program, contributes to her continuous professional development and engagement with IBM''s learning initiatives, aligning with her role in managing technology and processes.
Shelia Sun manages delivery failures and system auto-replies, coordinating with stakeholders like Cara Gao, Harry Jhan, and WISE support. Ensure procedural steps are in place for managing communication challenges related to delivery failures, particularly ''The Ouai Order Report.''
Shelia Sun is actively involved in industry reports and executive insights, focusing on managing document validation processes and ensuring effective communication with key stakeholders like Brielle Enz-Meltz and Marcy Langstein.
Frances Parro Belleza is an IT Systems Support Manager at ITEM, involved in EDI process management and order type resolutions. Michael Jan Francisco is a System Implementation Manager at ITEM, responsible for overseeing system implementations and addressing order type issues. Their roles highlight their involvement in collaborative problem-solving and decision-making processes within ITEM, enhancing the professional network Shelia Sun interacts with.','5000','{}','org-00000000-0000-4000-8000-000000000000','user-43a92772-e76b-4e5d-a1bd-3d32992580f9','block-a9ab5990-e04a-4ae2-91cf-3a6c17f4a0ea','2025-10-19 07:12:42.627886+00','2025-10-19 20:16:46.20339+00','false','user-43a92772-e76b-4e5d-a1bd-3d32992580f9','user-43a92772-e76b-4e5d-a1bd-3d32992580f9');
